#include <stdio.h>

int queue[10];
int front = 0, rear = 0;

void enqueue(int value) {
    queue[rear++] = value;
}

int dequeue() {
    return queue[front++];
}

int main() {
    enqueue(1);
    enqueue(2);
    enqueue(3);
    printf("%d ", dequeue());
    printf("%d ", dequeue());
    enqueue(4);
    printf("%d ", dequeue());
    printf("%d\n", dequeue());
    return 0;
}
